import '@servicenow/sdk/global'
import { Flow, trigger, wfa } from '@servicenow/sdk/automation'
import { StringColumn } from '@servicenow/sdk/core'

/**
 * Simple example of setFlowVariables in a Flow
 * Tests that string literal values are preserved during build and transform
 */
export const setFlowVariablesSimpleExample = Flow(
    {
        $id: Now.ID['set_flow_variables_simple_example'],
        name: 'SetFlowVariables Simple Example',
        description: 'Demonstrates basic usage of setFlowVariables',
        flowPriority: 'MEDIUM',
        runAs: 'system',
        runWithRoles: [],
        flowVariables: {
            status: StringColumn({ label: 'Status', mandatory: false }),
            count: StringColumn({ label: 'Count', mandatory: false }),
            isActive: StringColumn({ label: 'Is Active', mandatory: false }),
        },
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['set_flow_vars_simple_trigger'] },
        {
            table: 'incident',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (params) => {
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['set_flow_vars_simple'],
                annotation: 'Set basic flow variables',
            },
            params.flowVariables,
            {
                status: 'active',
                count: '42',
                isActive: 'true',
            }
        )
    }
)
